import React, { useState, useEffect } from "react";
import VerticalNavbar from "../Vertical_Navbar/vertical_navbar";
import HorizontalNavbar from "../Horizontal_Navbar/horizontal_navbar";
import requestApi from "../../utils/axios";
import { DatePicker } from "@mui/x-date-pickers/DatePicker";
import dayjs from "dayjs";
import { DemoContainer } from "@mui/x-date-pickers/internals/demo";
import axios from "axios";
import Cookies from "js-cookie";
import apiHost from "../../utils/api";
import { LocalizationProvider } from "@mui/x-date-pickers/LocalizationProvider";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import { toast, ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import Dialog from "@mui/material/Dialog";
import DialogContent from "@mui/material/DialogContent";
import DialogTitle from "@mui/material/DialogTitle";
import InputBox from "../InputBox/inputbox";
import "./ProductDashboard.css";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import SearchSharpIcon from "@mui/icons-material/SearchSharp";
import CustomDatePicker from "../InputBox/datepicker";

const CategoryTable = () => {
  const [selectedDate, setSelectedDate] = useState(dayjs());
  const [data, setData] = useState([]);
  const [editingItem, setEditingItem] = useState(null);
  const [editopen, setEditOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");

  const handleEditOpen = () => {
    setEditOpen(true);
  };
  const handleEditClose = () => {};
  const handleDateChange = async (newValue) => {
    setSelectedDate(newValue);
  };

  const notifySuccess = (message) => {
    toast.success(message, { position: toast.POSITION.BOTTOM_LEFT });
  };

  const notifyError = (message) => {
    toast.error(message, { position: toast.POSITION.BOTTOM_LEFT });
  };

  useEffect(() => {
    fetchData(selectedDate);
  }, [selectedDate]); // Added selectedDate to the dependency array

  const fetchData = async (date) => {
    try {
      const queryParams = new URLSearchParams({
        date: date.format("YYYY-MM-DD"),
      });
      const response = await requestApi(
        "GET",
        `/api/stock/stock?${queryParams}`
      );
      setData(response.data);
    } catch (error) {}
  };

  const handleEdit = (item) => {
    setEditingItem(item);
    handleEditOpen();
  };

  const handleDelete = async (id) => {
    try {
      const token = Cookies.get("token");
      const headers = {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      };

      const data = { id: id };
      const response = await axios.delete(`${apiHost}/api/stock/stock`, {
        headers,
        data,
      });

      if (response.status >= 200 && response.status < 300) {
        notifySuccess("Stock Deleted Successfully");
        fetchData(selectedDate);

        setData(stocklist.filter((item) => item.id !== id));
      } else {
        throw new Error(`Error deleting row: ${response.status}`);
      }
    } catch (error) {
      notifyError("Failed to Delete Stock");
    }
  };

  const handleSave = async () => {
    try {
      const token = Cookies.get("token");
      const headers = {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      };

      const requestBody = {
        id: editingItem.id,
        selling_price: editingItem.selling_price,
        mrp: editingItem.mrp,
        quantity: parseInt(editingItem.quantity),
      };

      const response = await axios.put(
        `${apiHost}/api/stock/stock`,
        requestBody,
        {
          headers,
        }
      );

      if (response.status === 200) {
        notifySuccess("Stock Edited Successfull");
        fetchData(selectedDate);

        setData(
          data.map((item) => (item.id === editingItem.id ? editingItem : item))
        );
        setEditOpen(false);
      }
    } catch (error) {
      notifyError("Failed to Edit Stock");
    }
  };
  const handleSearch = (event) => {
    setSearchTerm(event.target.value);
  };

  const stocklist = data.filter(
    (item) =>
      item.date.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.shop.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.color_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.model_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.user.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.mrp.toString().includes(searchTerm) ||
      item.size_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.selling_price.toString().includes(searchTerm)
  );

  return (
    <div className="dashboard-container">
      <HorizontalNavbar />
      <div className="vandc-container">
        <VerticalNavbar />
        <ToastContainer />
        <div className="dashboard-body">
          <div className="total-table-container">
            <div className="date-picker-division">
              <div className="search-box-products">
                <InputBox
                  label={
                    <div style={{ display: "flex", alignItems: "center" }}>
                      <SearchSharpIcon sx={{ marginRight: 1 }} />
                      Search
                    </div>
                  }
                  type="text"
                  placeholder="Faculty Name/ID/Sub.."
                  value={searchTerm}
                  onChange={handleSearch}
                  size="small"
                />
              </div>
              <LocalizationProvider dateAdapter={AdapterDayjs}>
                <DemoContainer components={["DatePicker", "DatePicker"]}>
                  <CustomDatePicker
                    label="Select Date"
                    value={selectedDate}
                    onChange={handleDateChange}
                    size="small"
                  />
                </DemoContainer>
              </LocalizationProvider>
            </div>
            <div className="container-for-table">
              <table>
                <thead>
                  <tr>
                    <th>S.NO</th>
                    <th>SHOP</th>
                    <th>USER</th>
                    <th>DATE</th>
                    <th>TIME</th>
                    <th>NAME</th>
                    <th>MODEL</th>
                    <th>COLOR</th>
                    <th>SIZE</th>
                    <th>QUANTITY</th>
                    <th>MRP</th>
                    <th>SELLING PRICE</th>
                    <th>TOTAL</th>
                    <th>ACTIONS</th>
                  </tr>
                </thead>
                <tbody>
                  {stocklist.map((item, index) => (
                    <tr key={item.id}>
                      <td>{index + 1}</td>
                      <td>{item.shop}</td>
                      <td>{item.user}</td>
                      <td>{item.date}</td>
                      <td>{item.time}</td>
                      <td>{item.name}</td>
                      <td>{item.model_name}</td>
                      <td>{item.color_name}</td>
                      <td>{item.size_name}</td>
                      <td>{item.quantity}</td>
                      <td>{item.mrp}</td>
                      <td>{item.selling_price}</td>
                      <td>{item.total_price}</td>
                      <td>
                        <EditIcon
                          onClick={() => handleEdit(item)}
                          sx={{
                            marginRight: 2,
                            color: "var(--button)",
                            cursor: "pointer",
                          }}
                        />
                        <DeleteIcon
                          onClick={() => handleDelete(item.id)}
                          sx={{ color: "var(--button)", cursor: "pointer" }}
                        />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            {editopen && editingItem && (
              <Dialog
                fullWidth
                open={editopen}
                onClose={handleEditClose}
                PaperProps={{
                  style: {
                    padding: "20px",
                    backgroundColor: "var(--background-1)",
                  },
                }}
              >
                <form
                  className="form-dialog"
                  onSubmit={(e) => {
                    e.preventDefault();
                    handleSave();
                  }}
                >
                  <div className="dialog-content">
                    <DialogTitle
                      style={{
                        textAlign: "center",
                        color: "var(--text)",
                      }}
                    >
                      <h2>Edit</h2>
                    </DialogTitle>
                    <DialogContent
                      style={{
                        fontSize: 10,
                      }}
                    >
                      <br />
                      <InputBox
                        label="MRP"
                        type="number"
                        value={editingItem.mrp}
                        onChange={(e) =>
                          setEditingItem({
                            ...editingItem,
                            mrp: e.target.value,
                          })
                        }
                        size="small"
                        sx={{ width: "100%" }}
                      />
                      <br />
                      <InputBox
                        label="Selling Price"
                        type="number"
                        value={editingItem.selling_price}
                        onChange={(e) =>
                          setEditingItem({
                            ...editingItem,
                            selling_price: e.target.value,
                          })
                        }
                        size="small"
                        sx={{ width: "100%" }}
                      />
                      <br />
                      <InputBox
                        label="Quantity"
                        type="number"
                        value={editingItem.quantity}
                        onChange={(e) =>
                          setEditingItem({
                            ...editingItem,
                            quantity: e.target.value,
                          })
                        }
                        size="small"
                        sx={{ width: "100%" }}
                      />
                      <br />

                      <div className="float-right">
                        <button
                          className="add-button-dialog"
                          onClick={() => setEditOpen(false)}
                        >
                          CANCEL
                        </button>
                        <button className="add-button-dialog" type="submit">
                          EDIT
                        </button>
                      </div>
                    </DialogContent>
                  </div>
                </form>
              </Dialog>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default CategoryTable;
